begin;
select plan(14);
select has_table('public','delivery_settings','delivery settings exists');
select is(round(public.geographic_distance_km(40.087274,65.402551,40.087274,65.402551)::numeric,3),0.000::numeric,'same point distance is zero');
select lives_ok($$select public.create_public_order('{"id":"30000000-0000-4000-8000-000000000001","idempotencyKey":"30000000-0000-4000-8000-000000000001","customer":{"name":"Test","primaryPhone":"+998900000000"},"type":"DELIVERY","paymentMethod":"CASH","address":{"district":"Navoiy","street":"Test","house":"1","landmark":"Maktab","deliveryNotes":"","latitude":40.0873,"longitude":65.4026,"confidence":"COMPLETE","pinConfirmedAt":"2026-08-04T08:00:00Z","locationProvider":"mock"},"items":[{"menuItemId":"plov","quantity":1,"modifierIds":[],"instructions":""}]}'::jsonb)$$,'in-zone order accepted');
select is((select delivery_fee from orders where id='30000000-0000-4000-8000-000000000001'),10000,'server calculates base delivery fee');
select is((select total from orders where id='30000000-0000-4000-8000-000000000001'),58000,'server calculates authoritative menu total');
select ok((select delivery_distance_km<0.1 from customer_addresses where order_id='30000000-0000-4000-8000-000000000001'),'server stores distance');
select throws_ok($$select public.create_public_order('{"id":"30000000-0000-4000-8000-000000000002","customer":{"name":"Test","primaryPhone":"+998900000000"},"type":"DELIVERY","paymentMethod":"CASH","address":{"district":"Uzoq","street":"Uzoq","house":"1","landmark":"X","latitude":41,"longitude":67,"pinConfirmedAt":"2026-08-04T08:00:00Z"},"items":[{"menuItemId":"plov","quantity":1,"modifierIds":[]}]}'::jsonb)$$,'P0001','DELIVERY_OUTSIDE_ZONE|Bu manzil yetkazish hududidan tashqarida','outside zone rejected');
select throws_ok($$select public.calculate_delivery_quote(91,65,50000,'DELIVERY')$$,'22023','INVALID_COORDINATES|Xaritadan to‘g‘ri yetkazish nuqtasini tanlang','invalid coordinates rejected');
update delivery_settings set delivery_enabled=false;
select is((public.calculate_delivery_quote(40.0873,65.4026,50000,'DELIVERY')->>'zoneResult'),'DELIVERY_DISABLED','delivery disabled rejected in quote');
select throws_ok($$select public.create_public_order('{"id":"30000000-0000-4000-8000-000000000004","customer":{"name":"Test","primaryPhone":"+998900000000"},"type":"DELIVERY","paymentMethod":"CASH","address":{"district":"Navoiy","street":"Test","house":"1","landmark":"X","latitude":40.0873,"longitude":65.4026,"pinConfirmedAt":"2026-08-04T08:00:00Z"},"items":[{"menuItemId":"plov","quantity":1,"modifierIds":[]}]}'::jsonb)$$,'P0001','DELIVERY_DISABLED|Yetkazib berish vaqtincha o‘chirilgan','delivery-disabled order rejected');
update delivery_settings set delivery_enabled=true;
select is((public.calculate_delivery_quote(40.0873,65.4026,150000,'DELIVERY')->>'deliveryFee')::integer,0,'free threshold applies');
select throws_ok($$select public.create_public_order('{"id":"30000000-0000-4000-8000-000000000005","customer":{"name":"Test","primaryPhone":"+998900000000"},"type":"DELIVERY","paymentMethod":"CASH","address":{"district":"Navoiy","street":"Test","house":"1","landmark":"X","latitude":40.0873,"longitude":65.4026,"pinConfirmedAt":"2026-08-04T08:00:00Z"},"items":[{"menuItemId":"ayran","quantity":1,"modifierIds":[]}]}'::jsonb)$$,'P0001','MINIMUM_ORDER_NOT_MET|Yetkazish uchun eng kam buyurtma 40000 so‘m','minimum delivery order enforced');
select lives_ok($$select public.create_public_order('{"id":"30000000-0000-4000-8000-000000000003","customer":{"name":"Pickup","primaryPhone":"+998900000000"},"type":"PICKUP","paymentMethod":"CASH","items":[{"menuItemId":"ayran","quantity":1,"modifierIds":[]}]}'::jsonb)$$,'pickup bypasses coordinates and minimum');
select is((public.create_public_order('{"id":"30000000-0000-4000-8000-000000000099","idempotencyKey":"30000000-0000-4000-8000-000000000001","customer":{"name":"Changed","primaryPhone":"x"},"type":"PICKUP","paymentMethod":"CASH","items":[{"unitPrice":1,"quantity":1}]}'::jsonb)->>'id'),'30000000-0000-4000-8000-000000000001','idempotency returns original order');
select * from finish();
rollback;
